// Soma grammar for tree-sitter — generated by tools/gen_grammar.py from spec/soma.grammar; do not edit.
// A mechanical translation: precedence is in the layering of the expression rules, and the
// places where the grammar is ambiguous without a lexer's line breaks are listed as conflicts.
module.exports = grammar({
  name: 'soma',

  extras: $ => [/\s/, $.comment],
  word: $ => $.name,

  conflicts: $ => [
    [$.stmt, $.primary], [$.assign, $.primary], [$.record, $.primary], [$.lambda, $.primary],
    [$.postfix], [$.return], [$.if], [$.try], [$.arm], [$.pattern, $.loose], [$.require],
  ],

  rules: {
    root: $ => repeat($.top),
    top: $ => choice($.nominal, $.cell, $.skeleton, $.flesh, $.use_decl, $.protocol),
    use_decl: $ => token(/use[ \t]([^\n])*/),
    protocol: $ => seq("protocol", $.name, $.braces),
    nominal: $ => seq("cell", "type", $.name, "=", choice("Int", "Float", "String")),
    cell: $ => seq("cell", optional($.cell_kind), $.name, optional($.type_params), optional($.brackets), "{", repeat($.section), "}"),
    cell_kind: $ => choice("agent", "test", "type", "property", "checker", "backend", "builtin"),
    type_params: $ => seq("<", $.name, repeat(seq(",", $.name)), ">"),
    section: $ => choice($.face, $.memory, $.state, $.handler, $.every, $.after, $.const, $.interior, $.variants, $.loose_section, $.test_rule),
    const: $ => seq("const", $.name, "=", $.unary),
    interior: $ => seq("interior", "{", repeat(choice($.cell, $.skeleton)), "}"),
    skeleton: $ => seq("skeleton", optional("agent"), $.name, optional($.brackets), "{", repeat($.skeleton_section), "}"),
    skeleton_section: $ => choice($.face, $.memory, $.state, $.every, $.after, $.const, $.interior, $.loose_section),
    flesh: $ => seq("flesh", $.name, "{", repeat($.handler), "}"),
    loose_section: $ => seq(choice("rules", "runtime", "scale", "cost"), $.braces),
    face: $ => seq("face", "{", repeat($.face_decl), "}"),
    face_decl: $ => choice($.signal_decl, $.tool_decl, $.await_decl, $.given_decl, $.promise_decl),
    signal_decl: $ => seq("signal", $.name, "(", $.params, ")", optional(seq("->", $.type)), repeat(choice($.contract, $.frame_clause))),
    contract: $ => seq(choice("requires", "ensures"), $.expr),
    tool_decl: $ => seq("tool", $.name, "(", $.params, ")", optional(seq("->", $.type)), optional($.brackets), optional($.string), repeat($.frame_clause)),
    frame_clause: $ => choice($.frame_names, $.frame_moves),
    frame_names: $ => seq(choice("reads", "writes", "calls", "emits"), $.frame_path, repeat(seq(",", $.frame_path))),
    frame_moves: $ => seq("moves", optional(seq($.frame_path, ":")), $.frame_edge, repeat(seq(",", $.frame_edge))),
    frame_path: $ => seq($.name, optional(seq(".", $.name))),
    frame_edge: $ => seq(choice($.name, "*"), "->", choice($.name, "*")),
    await_decl: $ => seq("await", $.name, "(", $.params, ")", optional(seq("->", $.type))),
    given_decl: $ => seq("given", $.name, ":", $.type, optional(seq("where", $.braces))),
    promise_decl: $ => token(/promise[ \t]([^\n])*/),
    params: $ => optional(seq($.param, repeat(seq(",", $.param)), optional(","))),
    param: $ => seq($.name, optional(seq(":", $.type))),
    type: $ => seq($.name, optional(seq(".", $.name)), optional(seq("<", $.type, repeat(seq(",", $.type)), ">")), optional("?")),
    memory: $ => seq("memory", "{", repeat($.memory_item), "}"),
    memory_item: $ => choice($.invariant, $.slot),
    slot: $ => seq($.name, ":", $.type, optional($.brackets), optional(seq("=", $.expr))),
    invariant: $ => seq("invariant", $.expr),
    state: $ => seq("state", $.name, optional(seq(":", $.name)), optional($.brackets), "{", repeat($.state_item), "}"),
    state_item: $ => choice($.initial, $.transition),
    initial: $ => seq("initial", ":", $.name),
    transition: $ => seq(choice($.name, "*"), repeat1(seq("->", $.name)), optional(seq("except", $.brackets)), optional($.braces)),
    handler: $ => seq("on", $.name, "(", $.params, ")", optional(seq("->", $.type)), optional($.brackets), $.block),
    every: $ => seq("every", $.number, optional($.brackets), $.block),
    after: $ => seq("after", $.number, optional($.brackets), $.block),
    variants: $ => seq("variants", "{", repeat(seq($.variant, optional(","))), "}"),
    variant: $ => seq($.name, optional(choice(seq("(", $.type, repeat(seq(",", $.type)), ")"), seq("{", $.params, "}")))),
    test_rule: $ => choice($.assert, $.assert_fails, $.mock, $.property, $.let),
    assert: $ => seq("assert", $.expr),
    assert_fails: $ => seq("assert_fails", $.expr, optional(seq("matching", $.string))),
    mock: $ => seq("mock", $.name, optional(seq(".", $.name)), optional(choice(seq("error", $.string), $.expr))),
    property: $ => seq("property", $.string, "forall", $.name, ":", $.type, "in", $.expr, optional(seq("..", $.expr)), optional(seq("count", $.number)), "ensures", $.expr),
    block: $ => seq("{", repeat($.stmt), "}"),
    stmt: $ => choice($.let, $.return, $.if, $.for, $.while, $.emit, $.require, $.ensure, $.assign, ";", $.expr),
    let: $ => seq("let", $.name, optional(seq(":", $.type)), "=", $.expr),
    return: $ => seq("return", optional($.expr)),
    if: $ => seq("if", $.expr, $.block, optional(seq("else", choice($.if, $.block)))),
    for: $ => seq("for", optional($.brackets), $.name, optional(seq(",", $.name)), optional($.brackets), "in", $.expr, $.block),
    while: $ => seq("while", $.expr, $.block),
    emit: $ => seq(choice("emit", "signal"), $.name, "(", $.args, ")"),
    require: $ => seq("require", $.expr, "else", choice($.string, seq($.name, optional($.string)))),
    ensure: $ => seq("ensure", $.expr),
    assign: $ => seq($.name, repeat(choice(seq(".", $.name), seq("[", $.expr, "]"))), $.assign_op, $.expr),
    assign_op: $ => choice("=", "+=", "-=", "*=", "/="),
    expr: $ => seq($.or, repeat(seq("|>", $.or))),
    or: $ => seq($.and, repeat(seq("||", $.and))),
    and: $ => seq($.coalesce, repeat(seq("&&", $.coalesce))),
    coalesce: $ => seq($.comparison, repeat(seq("??", $.comparison))),
    comparison: $ => seq($.additive, repeat(seq($.compare_op, $.additive))),
    compare_op: $ => choice("==", "!=", "<=", ">=", "<", ">"),
    additive: $ => seq($.multiplicative, repeat(seq(choice("++", "+", "-"), $.multiplicative))),
    multiplicative: $ => seq($.unary, repeat(seq(choice("*", "/", "%"), $.unary))),
    unary: $ => choice(seq(choice("!", "-"), $.unary), $.postfix),
    postfix: $ => seq($.primary, repeat(choice(seq(".", $.name, optional(seq("(", $.args, ")"))), seq("[", $.expr, "]"), seq("(", $.args, ")"), "?"))),
    primary: $ => choice($.lambda, $.if, $.match, $.try, $.await, $.record, $.list, $.paren, $.string, $.number, $.name),
    lambda: $ => seq(choice($.name, seq("(", optional(seq($.name, repeat(seq(",", $.name)))), ")")), "=>", choice($.block, $.expr)),
    match: $ => seq("match", $.expr, "{", repeat(seq($.arm, optional(","))), "}"),
    arm: $ => seq($.pattern, repeat(seq("|", $.pattern)), optional(seq("if", $.expr)), choice("->", "=>"), choice($.block, $.stmt)),
    pattern: $ => choice(seq($.name, $.braces), $.braces, seq($.expr, optional(seq("..", $.expr)))),
    try: $ => seq("try", choice($.block, $.expr), optional(seq("catch", optional($.name), $.block))),
    await: $ => seq("await", $.name, "(", $.args, ")"),
    record: $ => seq($.name, "{", optional(seq($.field, repeat(seq(optional(","), $.field)))), optional(","), "}"),
    field: $ => seq($.name, ":", $.expr),
    list: $ => seq("[", optional(seq($.expr, repeat(seq(",", $.expr)), optional(","))), "]"),
    paren: $ => seq("(", optional($.expr), ")"),
    args: $ => optional(seq($.expr, repeat(seq(",", $.expr)), optional(","))),
    name: $ => token(/[a-zA-Z_]([a-zA-Z0-9_])*/),
    number: $ => token(/(0[xXbBoO]([0-9a-fA-F_])+|[0-9]([0-9_])*(\.[0-9]([0-9_])*)?([eE]([+-])?([0-9])+)?)((ms|s|min|h|d|years|%))?/),
    string: $ => token(/("""(([^"]|"[^"]|""[^"]))*"""|"(([^"\\]|\\[^\x00]))*")/),
    comment: $ => token(/(\/\/([^\n])*|\/\*(([^*]|(\*)+[^*\/]))*(\*)+\/)/),
    braces: $ => seq("{", repeat($.loose), "}"),
    brackets: $ => seq("[", repeat($.loose), "]"),
    parens: $ => seq("(", repeat($.loose), ")"),
    loose: $ => choice($.braces, $.brackets, $.parens, $.string, $.comment, $.filler),
    filler: $ => token(/(([^{}()\[\]"\/])+|\/)/),
  }
});
